export const counts = { useValue: 0, useState: 0 }
export const requests = []
export const navigations = []
export const haptics = []
export const timers = []
let openState = false

export const atom = initial => {
  let value = initial
  const subs = new Set()
  return {
    get: () => value,
    set: next => {
      value = next
      subs.forEach(fn => fn(next))
    },
    listen: fn => {
      subs.add(fn)
      return () => subs.delete(fn)
    }
  }
}

export const computed = (source, fn) => {
  const out = atom(fn(source ? source.get() : undefined))
  if (source && source.listen) source.listen(() => out.set(fn(source.get())))
  return out
}

export const useValue = a => {
  counts.useValue += 1
  if (!a || typeof a.get !== 'function') return null
  const value = a.get()
  // Return a shallow copy of objects so renders cannot mutate the atom's value.
  if (value && typeof value === 'object') {
    if (Array.isArray(value)) return value.slice()
    return { ...value }
  }
  return value
}

let rpcImpl = async () => ({})
export const setRpc = fn => {
  rpcImpl = fn
}

export const host = {
  state: {
    activeSessionId: atom(null),
    cwd: atom('/home/ubuntu'),
    focusedSessionId: atom(null),
    focusedStoredSessionId: atom(null),
    focusedUsage: atom(null),
    gateway: atom('open'),
    model: atom(''),
    profile: atom('default'),
    viewport: atom({ height: 800, narrow: false, width: 1400 })
  },
  request: (method, params) => {
    requests.push({ method, params })
    return rpcImpl(method, params)
  },
  onEvent: () => () => {},
  notify: () => {},
  navigate: path => navigations.push(path),
  logs: async () => {},
  status: async () => ({})
}

