export const icons = {}

export const useState = initial => {
  counts.useState += 1
  if (typeof initial === 'boolean') {
    const value = openState
    return [value, v => { openState = typeof v === 'function' ? v(value) : v }]
  }
  return [initial, () => {}]
}
